local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

local player = Players.LocalPlayer
local playerGui = player:WaitForChild("PlayerGui")

local virtualInputManager = nil
pcall(function()
	virtualInputManager = game:GetService("VirtualInputManager")
end)

local function hasExecutorMouse()
	return typeof(mousemoverel) == "function" or typeof(mousemoveabs) == "function" or typeof(mouse1press) == "function" or typeof(mouse1click) == "function" or typeof(mousescroll) == "function"
end

local function getMouseScreenPosition()
	local location = UserInputService and UserInputService:GetMouseLocation()
	return Vector2.new(location.X, location.Y)
end

local function findByPath(path)
	if path == nil or path == "" then return nil end
	local current = game
	for name in string.gmatch(path, "[^/]+") do
		current = current:FindFirstChild(name)
		if not current then return nil end
	end
	return current
end

