local hasRawMouseActions = false
for _, action in ipairs(actions) do
	if action.type == "mouseMove" or action.type == "mouseDown" or action.type == "mouseUp" then
		hasRawMouseActions = true
		break
	end
end

local function findGuiButton(guiPath, guiName)
	local button = findByPath(guiPath)
	if button and button:IsA("GuiButton") then return button end
	if button then
		local parent = button.Parent
		while parent and parent ~= playerGui do
			if parent:IsA("GuiButton") then return parent end
			parent = parent.Parent
		end
		local descendantButton = button:FindFirstChildWhichIsA("GuiButton", true)
		if descendantButton then return descendantButton end
	end
	for _, item in ipairs(playerGui:GetDescendants()) do
		if item:IsA("GuiButton") and item.Name == guiName then return item end
	end
	return nil
end

local function isTowerGuiPath(guiPath)
	if not guiPath then return false end
	local lowerPath = string.lower(guiPath)
	return string.find(lowerPath, "reactuniversalhotbar", 1, true) ~= nil
		or string.find(lowerPath, "/troops/", 1, true) ~= nil
		or string.find(lowerPath, "upgrade", 1, true) ~= nil
		or string.find(lowerPath, "upgrades", 1, true) ~= nil
		or string.find(lowerPath, "sell", 1, true) ~= nil
		or string.find(lowerPath, "target", 1, true) ~= nil
		or string.find(lowerPath, "ability", 1, true) ~= nil
end

local function findClickDetector(target)
	if not target then return nil end
	local direct = target:FindFirstChildWhichIsA("ClickDetector")
	if direct then return direct end
	local parent = target.Parent
	while parent and parent ~= game do
		local clickDetector = parent:FindFirstChildWhichIsA("ClickDetector")
		if clickDetector then return clickDetector end
		parent = parent.Parent
	end
	return nil
end

local function clickAtScreenPosition(screenPosition)
	if not screenPosition then return false end
	if virtualInputManager then
		local ok = pcall(function()
			pcall(function() virtualInputManager:SendMouseMoveEvent(screenPosition.X, screenPosition.Y, game) end)
			task.wait(0.03)
			virtualInputManager:SendMouseButtonEvent(screenPosition.X, screenPosition.Y, 0, true, game, 0)
			task.wait(0.07)
			virtualInputManager:SendMouseButtonEvent(screenPosition.X, screenPosition.Y, 0, false, game, 0)
		end)
		if ok then return true end
	end
	local executorOk = pcall(function()
		if typeof(mousemoveabs) == "function" then
			mousemoveabs(screenPosition.X, screenPosition.Y)
		elseif typeof(mousemoverel) == "function" then
			local current = getMouseScreenPosition()
			mousemoverel(screenPosition.X - current.X, screenPosition.Y - current.Y)
		end
		task.wait(0.03)
		if typeof(mouse1press) == "function" and typeof(mouse1release) == "function" then
			mouse1press()
			task.wait(0.07)
			mouse1release()
		elseif typeof(mouse1click) == "function" then
			mouse1click()
		else
			error("No mouse click function available")
		end
	end)
	return executorOk
end

local function getCamera()
	return workspace.CurrentCamera
end

local function resolveScreenPosition(action)
	if not action or not action.screenPosition then return nil end
	local camera = getCamera()
	if not camera or not action.viewportSize then return action.screenPosition end
	local currentSize = camera.ViewportSize
	if action.viewportSize.X <= 0 or action.viewportSize.Y <= 0 then return action.screenPosition end
	return Vector2.new(action.screenPosition.X * currentSize.X / action.viewportSize.X, action.screenPosition.Y * currentSize.Y / action.viewportSize.Y)
end

local function resolveWorldScreenPosition(action)
	if not action or not action.position then return nil end
	local camera = getCamera()
	if not camera then return nil end
	local viewportPoint, onScreen = camera:WorldToViewportPoint(action.position)
	if not onScreen then return nil end
	return Vector2.new(viewportPoint.X, viewportPoint.Y)
end

local function applyCameraState(action)
	if not action or not action.cameraCFrame then return end
	local camera = getCamera()
	if not camera then return end
	camera.CFrame = action.cameraCFrame
	if action.cameraFocus then camera.Focus = action.cameraFocus end
	if action.cameraFov then camera.FieldOfView = action.cameraFov end
	RunService.RenderStepped:Wait()
end

local function moveMouseToAction(action)
	applyCameraState(action)
	local screenPosition
	if action.overGui then
		screenPosition = resolveScreenPosition(action)
	else
		screenPosition = resolveWorldScreenPosition(action) or resolveScreenPosition(action)
	end
	if not screenPosition then return false end
	if virtualInputManager then
		pcall(function() virtualInputManager:SendMouseMoveEvent(screenPosition.X, screenPosition.Y, game) end)
		task.wait(0.02)
		return true
	end
	local ok = pcall(function()
		if typeof(mousemoveabs) == "function" then
			mousemoveabs(screenPosition.X, screenPosition.Y)
		elseif typeof(mousemoverel) == "function" then
			local current = getMouseScreenPosition()
			mousemoverel(screenPosition.X - current.X, screenPosition.Y - current.Y)
		else
			error("No mouse move function available")
		end
	end)
	task.wait(0.02)
	return ok
end

local function replayRawMouse(action)
	if not moveMouseToAction(action) then return end
	local screenPosition
	if action.overGui then
		screenPosition = resolveScreenPosition(action)
	else
		screenPosition = resolveWorldScreenPosition(action) or resolveScreenPosition(action)
	end
	if not screenPosition then return end
	if virtualInputManager then
		if action.type == "mouseDown" then
			pcall(function() virtualInputManager:SendMouseButtonEvent(screenPosition.X, screenPosition.Y, 0, true, game, 0) end)
		elseif action.type == "mouseUp" then
			pcall(function() virtualInputManager:SendMouseButtonEvent(screenPosition.X, screenPosition.Y, 0, false, game, 0) end)
			if not action.overGui then
				task.wait(0.10)
				clickAtScreenPosition(screenPosition)
			end
		end
	else
		if action.type == "mouseDown" and typeof(mouse1press) == "function" then
			pcall(mouse1press)
		elseif action.type == "mouseUp" and typeof(mouse1release) == "function" then
			pcall(mouse1release)
			if not action.overGui then
				task.wait(0.10)
				clickAtScreenPosition(screenPosition)
			end
		end
	end
end

local function replayMouseWheel(action)
	if not moveMouseToAction(action) then return end
	local screenPosition
	if action.overGui then
		screenPosition = resolveScreenPosition(action)
	else
		screenPosition = resolveWorldScreenPosition(action) or resolveScreenPosition(action)
	end
	if not screenPosition then return end
	local wheelDelta = action.wheelDelta or 0
	if wheelDelta == 0 then return end
	if virtualInputManager then
		local steps = math.max(1, math.floor(math.abs(wheelDelta)))
		local isForward = wheelDelta > 0
		for _ = 1, steps do
			pcall(function() virtualInputManager:SendMouseWheelEvent(screenPosition.X, screenPosition.Y, isForward, game) end)
			task.wait(0.03)
		end
	elseif typeof(mousescroll) == "function" then
		pcall(function() mousescroll(wheelDelta) end)
	end
end

local function replayRawKey(action)
	if not virtualInputManager or not action.keyCodeName then return end
	local keyCode = Enum.KeyCode[action.keyCodeName]
	if not keyCode then return end
	applyCameraState(action)
	if action.type == "keyDown" then
		pcall(function() virtualInputManager:SendKeyEvent(true, keyCode, false, game) end)
	elseif action.type == "keyUp" then
		pcall(function() virtualInputManager:SendKeyEvent(false, keyCode, false, game) end)
	end
end

local function smoothMove(root, fromCFrame, toCFrame, duration)
	if duration <= 0 then root.CFrame = toCFrame return end
	local moveStart = os.clock()
	while os.clock() - moveStart < duration do
		local alpha = math.clamp((os.clock() - moveStart) / duration, 0, 1)
		alpha = alpha * alpha * (3 - 2 * alpha)
		root.CFrame = fromCFrame:Lerp(toCFrame, alpha)
		RunService.RenderStepped:Wait()
	end
	root.CFrame = toCFrame
end

local function replayGuiClick(action)
	local guiButton = findGuiButton(action.guiPath, action.guiName)
	applyCameraState(action)
	local screenPosition = resolveScreenPosition(action)
	local isTowerGui = action.isTowerGui or isTowerGuiPath(action.guiPath)
	if isTowerGui and guiButton and guiButton:IsA("GuiButton") then
		guiButton.Active = true
		guiButton.Selectable = true
		pcall(function() guiButton:Activate() end)
		task.wait(0.50)
		return
	end
	if screenPosition and clickAtScreenPosition(screenPosition) then task.wait(isTowerGui and 0.50 or 0.28) return end
	if guiButton and guiButton:IsA("GuiButton") then
		guiButton.Active = true
		guiButton.Selectable = true
		pcall(function() guiButton:Activate() end)
		task.wait(isTowerGui and 0.50 or 0.28)
		return
	end
	if screenPosition then clickAtScreenPosition(screenPosition) task.wait(isTowerGui and 0.50 or 0.28) end
end

local function replayGeneralClick(action)
	applyCameraState(action)
	local screenPosition = resolveWorldScreenPosition(action) or resolveScreenPosition(action)
	if screenPosition and clickAtScreenPosition(screenPosition) then task.wait(0.22) return end
	local target = findByPath(action.targetPath)
	local clickDetector = findClickDetector(target)
	if clickDetector and typeof(fireclickdetector) == "function" then
		pcall(function() fireclickdetector(clickDetector) end)
		task.wait(0.22)
	end
end


local RETURN_TO_LOBBY_PATHS = {
	"Players/" .. player.Name .. "/PlayerGui/ReactGameNewRewards/Frame/gameOver/RewardsScreen/ReturnToLobby/button",
	"Players/" .. player.Name .. "/PlayerGui/ReactGameNewRewards/Frame/gameOver/RewardsScreen/ReturnToLobby/content/button",
	"Players/" .. player.Name .. "/PlayerGui/ReactGameNewRewards/Frame/gameOver/RewardsScreen/ReturnToLobby",
}

local function isGuiActuallyVisible(guiObject)
	local current = guiObject
	while current and current ~= playerGui do
		if current:IsA("GuiObject") and not current.Visible then
			return false
		end
		current = current.Parent
	end
	return true
end

local function findReturnToLobbyButton()
	for _, path in ipairs(RETURN_TO_LOBBY_PATHS) do
		local item = findByPath(path)
		if item then
			if item:IsA("GuiButton") then
				return item
			end

			local button = item:FindFirstChildWhichIsA("GuiButton", true)
			if button then
				return button
			end
		end
	end

	local rewards = playerGui:FindFirstChild("ReactGameNewRewards")
	if rewards then
		local returnFrame = rewards:FindFirstChild("ReturnToLobby", true)
		if returnFrame then
			if returnFrame:IsA("GuiButton") then
				return returnFrame
			end

			local button = returnFrame:FindFirstChildWhichIsA("GuiButton", true)
			if button then
				return button
			end
		end
	end

	for _, item in ipairs(playerGui:GetDescendants()) do
		if item:IsA("GuiButton") then
			local lowerName = string.lower(item.Name)
			local parentName = item.Parent and string.lower(item.Parent.Name) or ""
			local text = ""
			pcall(function()
				text = string.lower(item.Text)
			end)

			if string.find(lowerName, "return", 1, true)
				or string.find(parentName, "returntolobby", 1, true)
				or string.find(text, "return", 1, true) then
				return item
			end
		end
	end

	return nil
end

local function clickReturnToLobbyWhenReady(timeoutSeconds)
	local start = os.clock()
	local lastButton = nil

	while os.clock() - start < timeoutSeconds do
		local button = findReturnToLobbyButton()

		if button and button:IsA("GuiButton") then
			lastButton = button
			button.Active = true
			button.Selectable = true

			local visible = isGuiActuallyVisible(button)
			local clickable = button.AbsoluteSize.X > 0 and button.AbsoluteSize.Y > 0

			if visible and clickable then
				pcall(function()
					button:Activate()
				end)

				pcall(function()
					firesignal(button.MouseButton1Click)
				end)

				pcall(function()
					firesignal(button.Activated)
				end)

				local center = button.AbsolutePosition + (button.AbsoluteSize / 2)
				pcall(function()
					clickAtScreenPosition(Vector2.new(center.X, center.Y))
				end)

				print("Clicked ReturnToLobby button.")
				return true
			end
		end

		task.wait(0.25)
	end

	warn("ReturnToLobby button was not clickable.", lastButton and lastButton:GetFullName() or "not found")
	return false
end

local character = player.Character or player.CharacterAdded:Wait()
local root = character:WaitForChild("HumanoidRootPart")
local humanoid = character:FindFirstChildOfClass("Humanoid")
local camera = getCamera()
local oldAnchored = root.Anchored
local oldCameraType = camera and camera.CameraType
local oldCameraSubject = camera and camera.CameraSubject
root.Anchored = true
if camera then camera.CameraType = Enum.CameraType.Scriptable end

local replayStart = os.clock()
local lastPositionAction = nil

for _, action in ipairs(actions) do
	local waitTime = action.t - (os.clock() - replayStart)
	if waitTime > 0 then task.wait(waitTime) end

	if action.type == "mouseMove" or action.type == "mouseDown" or action.type == "mouseUp" then
		replayRawMouse(action)
	elseif action.type == "mouseWheel" then
		replayMouseWheel(action)
	elseif action.type == "keyDown" or action.type == "keyUp" then
		replayRawKey(action)
	elseif action.type == "position" then
		local duration = 0
		if lastPositionAction then
			duration = math.clamp(action.t - lastPositionAction.t, 0.03, 0.25)
		end
		smoothMove(root, root.CFrame, action.cframe, duration)
		applyCameraState(action)
		lastPositionAction = action
	elseif action.type == "guiClick" and (not hasRawMouseActions or action.isTowerGui or isTowerGuiPath(action.guiPath)) then
		replayGuiClick(action)
	elseif action.type == "generalClick" and not hasRawMouseActions then
		replayGeneralClick(action)
	end
end

if humanoid then humanoid:Move(Vector3.zero, false) end
if camera then
	camera.CameraType = oldCameraType or Enum.CameraType.Custom
	camera.CameraSubject = oldCameraSubject
end
root.Anchored = oldAnchored

clickReturnToLobbyWhenReady(120)